import React, { useState } from 'react';
import './Branches.css';

const branchData = [
    {code:"002",branch:"Naubise, Dhading",name:"Shankar Singh Mahata",province:"Bagmati",phone:"9862547302",email:"naubise@infinitylbsl.com.np"},
    // ... Copy the rest of the branch list from your HTML script here
];

const Branches = () => {
  const [searchTerm, setSearchTerm] = useState("");

  const filteredBranches = branchData.filter(b => 
    Object.values(b).join(" ").toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="branch-container">
      <div className="title">🏢 Branch Network</div>
      <input 
        type="text" 
        className="search-box" 
        placeholder="🔍 Search branch, manager, province..." 
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <div className="table-wrapper">
        <table>
          <thead>
            <tr>
              <th>Code</th>
              <th>Branch</th>
              <th>Manager</th>
              <th>Province</th>
              <th>Contact</th>
            </tr>
          </thead>
          <tbody>
            {filteredBranches.map((b, i) => (
              <tr key={i}>
                <td>{b.code}</td>
                <td>📍 {b.branch}</td>
                <td>👤 {b.name}</td>
                <td><span className="badge">{b.province}</span></td>
                <td>📞 {b.phone}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Branches;
